import {objectComponents} from './scene-components.js';
const visualTypes=new Set(['Rope2D','Cloth','RaycastVehicle','ReflectionProbe','MeshRenderer','SpriteRenderer','SpriteSkin','TilemapRenderer','SpriteMask','SortingGroup','ShadowCaster2D','CompositeShadowCaster2D','Decal','ParticleSystem','NavigationMesh','NavigationGrid','NavigationArea','Camera','DirectionalLight','PointLight','SpotLight','Light2D','Renderer2D','SkyLight']);
export const visualComponentSignature=object=>JSON.stringify(objectComponents(object).filter(c=>visualTypes.has(c.type)||c.type==='PostProcessVolume'||c.type==='TextureStreaming').map(c=>c.type==='RaycastVehicle'?{type:c.type,enabled:c.properties?.enabled,showWheels:c.properties?.showWheels,wheels:c.properties?.wheels}:c.type==='PostProcessVolume'?{type:c.type,enabled:c.properties?.enabled,colorLookup:c.properties?.colorLookup,pathTracingHDRI:c.properties?.pathTracingHDRI}:c.type==='SkyLight'?{type:c.type,enabled:c.properties?.enabled,source:c.properties?.source,cubemap:c.properties?.cubemap}:c));
